      controls: [{ method: "GET", path: "/v1/control-tests" }, { method: "POST", path: "/v1/control-tests" }, { method: "POST", path: "/v1/control-tests/:testId/results" }],
      events: [{ method: "GET", path: "/v1/events" }, { method: "POST", path: "/v1/events" }],
