      triage: [{ method: "GET", path: "/v1/triage/shifts" }, { method: "POST", path: "/v1/triage/shifts" }, { method: "GET", path: "/v1/triage/queue" }, { method: "POST", path: "/v1/triage/queue/admit" }, { method: "POST", path: "/v1/triage/overflow" }, { method: "POST", path: "/v1/containment-actions" }, { method: "POST", path: "/v1/containment-actions/:actionId/override" }],
